//! The community catalog: packages the person chose to add from Discover. Each is stored as a small manifest file in the data
//! folder (never in the program folder) and loaded back at start-up. The manifest is *generated by the application* from the
//! package's published facts; the person's choice is only "this package id". Loaded files are checked again so a hand-edited file
//! cannot gain run profiles or other install methods.

use crate::adapters::registry::ManifestRegistry;
use crate::domain::discover::{community_manifest_toml, community_ok, community_tool_id, is_community_id, DiscoverResult};
use crate::domain::manifest::{InstallSpec, ToolManifest};
use crate::domain::process::CancellationToken;
use crate::domain::{AppError, AppResult, ToolId};
use crate::ports::{CatalogEntry, PackageDiscovery, ToolQuery, ToolRegistry, TrustLevel};
use sha2::{Digest, Sha256};
use std::path::PathBuf;
use std::sync::Arc;

pub struct CommunityCatalog {
    dir: PathBuf,
    registry: Arc<ManifestRegistry>,
    discovery: Arc<dyn PackageDiscovery>,
    /// Whether a tool is installed or being installed (it must be uninstalled before it can be removed from the catalog).
    in_use: Arc<dyn Fn(&ToolId) -> bool + Send + Sync>,
}

fn today() -> String {
    chrono::Utc::now().format("%Y-%m-%d").to_string()
}

fn winget_id_of(m: &ToolManifest) -> Option<&str> {
    match m.install.first() {
        Some(InstallSpec::Winget { package_id }) => Some(package_id.as_str()),
        _ => None,
    }
}

impl CommunityCatalog {
    pub fn new(dir: PathBuf, registry: Arc<ManifestRegistry>, discovery: Arc<dyn PackageDiscovery>, in_use: Arc<dyn Fn(&ToolId) -> bool + Send + Sync>) -> Self {
        Self { dir, registry, discovery, in_use }
    }

    /// Load the entries added earlier. Invalid or over-privileged files are skipped and reported.
    pub fn load(&self) -> Vec<String> {
        Self::load_dir(&self.dir, &self.registry)
    }

    /// Same, before the catalog object exists (the installer needs the registry first).
    pub fn load_dir(dir: &std::path::Path, registry: &ManifestRegistry) -> Vec<String> {
        let mut problems = vec![];
        let Ok(rd) = std::fs::read_dir(dir) else { return problems };
        let mut paths: Vec<_> = rd.filter_map(Result::ok).map(|e| e.path()).filter(|p| p.extension().is_some_and(|x| x == "toml")).take(200).collect();
        paths.sort();
        for p in paths {
            let result = (|| -> AppResult<()> {
                let meta = std::fs::symlink_metadata(&p)?;
                if !meta.file_type().is_file() || meta.len() > 64 * 1024 {
                    return Err(AppError::Validation("not a regular, small file".into()));
                }
                let text = std::fs::read_to_string(&p)?;
                let m = ToolManifest::from_toml(&text)?;
                community_ok(&m)?;
                if p.file_stem().and_then(|s| s.to_str()) != Some(m.id.as_str()) {
                    return Err(AppError::Validation("the file name does not match the tool id".into()));
                }
                let digest = sha_hex(text.as_bytes());
                registry.add_entry(m, TrustLevel::RemoteUnsigned, digest).map(|_| ())
            })();
            if let Err(e) = result {
                problems.push(format!("{}: {e}", p.display()));
            }
        }
        problems
    }

    /// Search winget and mark what the catalog already has.
    pub async fn search(&self, query: &str, cancel: &CancellationToken) -> AppResult<Vec<DiscoverResult>> {
        let found = self.discovery.search(query, cancel).await?;
        let entries = self.registry.list(&ToolQuery::default());
        Ok(found
            .into_iter()
            .map(|package| {
                let hit = entries.iter().find(|e| winget_id_of(&e.manifest).is_some_and(|w| w.eq_ignore_ascii_case(&package.id)));
                DiscoverResult { in_catalog: hit.map(|e| e.manifest.id.as_str().to_string()), in_catalog_is_community: hit.is_some_and(|e| e.trust != TrustLevel::Bundled), package }
            })
            .collect())
    }

    pub async fn details(&self, id: &str, cancel: &CancellationToken) -> AppResult<crate::domain::discover::DiscoveredDetails> {
        self.discovery.details(id, cancel).await
    }

    /// Add a package to the catalog as a community entry. The facts are read again from winget here; nothing comes from the interface
    /// but the package id. Adding installs nothing.
    pub async fn add(&self, id: &str, cancel: &CancellationToken) -> AppResult<CatalogEntry> {
        let details = self.discovery.details(id, cancel).await?;
        if self.registry.list(&ToolQuery::default()).iter().any(|e| winget_id_of(&e.manifest).is_some_and(|w| w.eq_ignore_ascii_case(&details.id))) {
            return Err(AppError::Validation("that package is already in the catalog".into()));
        }
        let (toml, manifest) = community_manifest_toml(&details, &today())?;
        std::fs::create_dir_all(&self.dir)?;
        let path = self.dir.join(format!("{}.toml", manifest.id));
        let tmp = self.dir.join(format!("{}.toml.tmp", manifest.id));
        std::fs::write(&tmp, toml.as_bytes())?;
        std::fs::rename(&tmp, &path)?;
        let digest = sha_hex(toml.as_bytes());
        match self.registry.add_entry(manifest, TrustLevel::RemoteUnsigned, digest) {
            Ok(e) => Ok(e),
            Err(e) => {
                let _ = std::fs::remove_file(&path);
                Err(e)
            }
        }
    }

    /// Remove a community entry from the catalog. It must not be installed (uninstall it first), and reviewed entries cannot be removed.
    pub fn remove(&self, id: &str) -> AppResult<()> {
        let tid = ToolId::new(id.to_string())?;
        if !is_community_id(id) || community_tool_id(id) == "" {
            return Err(AppError::Validation("only community entries can be removed".into()));
        }
        if (self.in_use)(&tid) {
            return Err(AppError::Validation("uninstall it first, then remove it from the catalog".into()));
        }
        self.registry.remove_entry(&tid)?;
        let _ = std::fs::remove_file(self.dir.join(format!("{id}.toml")));
        Ok(())
    }
}

fn sha_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes).iter().map(|b| format!("{b:02x}")).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::domain::discover::{DiscoveredDetails, DiscoveredPackage};
    use async_trait::async_trait;
    use std::sync::atomic::{AtomicBool, Ordering};

    struct Fake;
    #[async_trait]
    impl PackageDiscovery for Fake {
        async fn search(&self, _: &str, _: &CancellationToken) -> AppResult<Vec<DiscoveredPackage>> {
            Ok(vec![
                DiscoveredPackage { id: "Insecure.Nmap".into(), name: "Nmap".into(), version: "7.80".into(), matched: String::new() },
                DiscoveredPackage { id: "Vendor.Cool-Tool".into(), name: "Cool Tool".into(), version: "2.1".into(), matched: String::new() },
            ])
        }
        async fn details(&self, id: &str, _: &CancellationToken) -> AppResult<DiscoveredDetails> {
            Ok(DiscoveredDetails { id: id.into(), name: "Cool Tool".into(), version: "2.1".into(), publisher: "Vendor Inc".into(), homepage: "https://vendor.example".into(), license: "MIT".into(), description: "Does cool things. Really.".into(), installer_type: "exe".into(), installer_sha256: "ab".repeat(32), ..Default::default() })
        }
    }

    fn repo_registry() -> Arc<ManifestRegistry> {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("manifests");
        Arc::new(ManifestRegistry::load_dir(&dir, TrustLevel::Bundled).unwrap())
    }

    fn catalog(dir: &std::path::Path, registry: Arc<ManifestRegistry>, in_use: Arc<AtomicBool>) -> CommunityCatalog {
        CommunityCatalog::new(dir.to_path_buf(), registry, Arc::new(Fake), Arc::new(move |_| in_use.load(Ordering::SeqCst)))
    }

    #[tokio::test]
    async fn adding_a_package_creates_an_unreviewed_entry_that_survives_a_restart_and_installs_nothing() {
        let tmp = tempfile::tempdir().unwrap();
        let c = catalog(tmp.path(), repo_registry(), Default::default());
        let entry = c.add("Vendor.Cool-Tool", &CancellationToken::new()).await.unwrap();
        assert_eq!(entry.manifest.id.as_str(), "community-vendor-cool-tool");
        assert_eq!(entry.trust, TrustLevel::RemoteUnsigned);
        assert!(entry.manifest.launch_profiles.is_empty());
        assert!(tmp.path().join("community-vendor-cool-tool.toml").exists());
        assert!(c.registry.get(&entry.manifest.id).is_ok());
        // Adding the same package twice, or one the reviewed catalog already installs, is refused.
        assert!(c.add("Vendor.Cool-Tool", &CancellationToken::new()).await.is_err());
        let e = c.add("Insecure.Nmap", &CancellationToken::new()).await.unwrap_err();
        assert!(e.to_string().contains("already in the catalog"), "{e}");
        // A restart: the entry is back, still unreviewed; reviewed entries are untouched.
        let fresh = repo_registry();
        let before = fresh.list(&Default::default()).len();
        assert!(CommunityCatalog::load_dir(tmp.path(), &fresh).is_empty());
        assert_eq!(fresh.list(&Default::default()).len(), before + 1);
        assert_eq!(fresh.get(&ToolId::new("community-vendor-cool-tool").unwrap()).unwrap().trust, TrustLevel::RemoteUnsigned);
        assert_eq!(fresh.get(&ToolId::new("nmap").unwrap()).unwrap().trust, TrustLevel::Bundled);
    }

    #[tokio::test]
    async fn search_results_say_what_the_catalog_already_has() {
        let tmp = tempfile::tempdir().unwrap();
        let c = catalog(tmp.path(), repo_registry(), Default::default());
        let r = c.search("nmap", &CancellationToken::new()).await.unwrap();
        assert_eq!(r[0].in_catalog.as_deref(), Some("nmap"));
        assert!(!r[0].in_catalog_is_community);
        assert_eq!(r[1].in_catalog, None);
        c.add("Vendor.Cool-Tool", &CancellationToken::new()).await.unwrap();
        let r = c.search("cool", &CancellationToken::new()).await.unwrap();
        assert!(r[1].in_catalog_is_community && r[1].in_catalog.as_deref() == Some("community-vendor-cool-tool"));
    }

    #[tokio::test]
    async fn files_in_the_community_folder_cannot_gain_privileges_or_replace_reviewed_tools() {
        let tmp = tempfile::tempdir().unwrap();
        let c = catalog(tmp.path(), repo_registry(), Default::default());
        c.add("Vendor.Cool-Tool", &CancellationToken::new()).await.unwrap();
        let good = std::fs::read_to_string(tmp.path().join("community-vendor-cool-tool.toml")).unwrap();
        // 1. A run profile added by hand.
        let with_profile = format!("{good}\n[[launch_profiles]]\nid = \"run\"\nlabel = \"Run\"\nruntime = \"windows_native\"\nexecutable = \"calc.exe\"\nargs = []\n");
        std::fs::write(tmp.path().join("community-vendor-cool-tool.toml"), with_profile).unwrap();
        // 2. A file that claims a reviewed tool's id.
        std::fs::write(tmp.path().join("nmap.toml"), good.replace("community-vendor-cool-tool", "nmap")).unwrap();
        // 3. A name that does not match the id.
        std::fs::write(tmp.path().join("other.toml"), good.replace("community-vendor-cool-tool", "community-other")).unwrap();
        // 4. Not a manifest.
        std::fs::write(tmp.path().join("junk.toml"), "this is not toml [[[").unwrap();
        let fresh = repo_registry();
        let before = fresh.list(&Default::default()).len();
        let problems = CommunityCatalog::load_dir(tmp.path(), &fresh);
        assert_eq!(problems.len(), 4, "{problems:?}");
        assert_eq!(fresh.list(&Default::default()).len(), before, "none of them was loaded");
        assert!(fresh.get(&ToolId::new("nmap").unwrap()).unwrap().manifest.launch_profiles.iter().any(|p| p.id == "quick-scan"), "the reviewed nmap is unchanged");
    }

    #[tokio::test]
    async fn removing_is_only_for_community_entries_that_are_not_installed() {
        let tmp = tempfile::tempdir().unwrap();
        let in_use = Arc::new(AtomicBool::new(false));
        let c = catalog(tmp.path(), repo_registry(), in_use.clone());
        c.add("Vendor.Cool-Tool", &CancellationToken::new()).await.unwrap();
        assert!(c.remove("nmap").is_err(), "reviewed entries cannot be removed");
        in_use.store(true, Ordering::SeqCst);
        assert!(c.remove("community-vendor-cool-tool").unwrap_err().to_string().contains("uninstall it first"));
        in_use.store(false, Ordering::SeqCst);
        c.remove("community-vendor-cool-tool").unwrap();
        assert!(!tmp.path().join("community-vendor-cool-tool.toml").exists());
        assert!(c.registry.get(&ToolId::new("community-vendor-cool-tool").unwrap()).is_err());
        assert!(c.registry.get(&ToolId::new("nmap").unwrap()).is_ok());
    }
}

#[cfg(test)]
mod live_tests {
    use super::*;

    /// Opt-in: the real winget builds a community entry for a real package. Installs nothing.
    /// `cargo test --lib live_community -- --ignored --nocapture`
    #[tokio::test]
    #[ignore = "runs the real winget and uses the network"]
    async fn live_community_add_from_real_winget() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("..").join("manifests");
        let registry = Arc::new(ManifestRegistry::load_dir(&dir, TrustLevel::Bundled).unwrap());
        let tmp = tempfile::tempdir().unwrap();
        let discovery = Arc::new(crate::adapters::discovery::WingetDiscovery::new(Arc::new(crate::adapters::executor::SystemCommandExecutor), Arc::new(crate::adapters::locator::SystemExecutableLocator)));
        let c = CommunityCatalog::new(tmp.path().to_path_buf(), registry, discovery, Arc::new(|_| false));
        let found = c.search("x64dbg", &CancellationToken::new()).await.unwrap();
        println!("search: {:?}", found.iter().map(|r| (&r.package.id, &r.in_catalog)).collect::<Vec<_>>());
        let e = c.add("x64dbg.x64dbg", &CancellationToken::new()).await.unwrap();
        println!("added {} (pinned {:?}, trust {:?}, profiles {})", e.manifest.id, e.manifest.version.pinned, e.trust, e.manifest.launch_profiles.len());
        println!("{}", std::fs::read_to_string(tmp.path().join(format!("{}.toml", e.manifest.id))).unwrap().lines().take(14).collect::<Vec<_>>().join("\n"));
        assert_eq!(e.trust, TrustLevel::RemoteUnsigned);
    }
}
